import{_ as r,l,o as e,c as n,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"减振与地基","description":"","frontmatter":{"title":"减振与地基","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/vibration-isolation.md","filePath":"litho/vibration-isolation.md","lastUpdated":1789023840000}'),_={name:"litho/vibration-isolation.md"};function c(m,a,u,f,A,E){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="减振与地基" tabindex="-1">减振与地基 <a class="header-anchor" href="#减振与地基" aria-label="Permalink to &quot;减振与地基&quot;">​</a></h1><div class="epigraph"><p>纳米套刻活在振动谱上。主动隔振把地脉动和泵声挡在台外，地基则决定厂里哪块地能放这台机器。</p><footer>—— 对照扫描机 isolation frame / 主动隔振公开描述</footer></div><p><a href="/litho/alignment-mark-design">上一课</a>把标记画完。缺口是环境力学：地脉动、空调、真空泵、邻机扫描反作用。本课钉减振与地基，台加速度下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>套刻 nm 对应台相对位移 nm。楼板模态若落在伺服带宽附近，闭环会放大。把残差全写成编码器，会去调错环。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>被动橡胶/气垫加主动惯性传感器反馈。机器要独立惯性块或指定地基刚度。厂务：邻近打桩、AGV 通道都进振动预算。验收用频谱，不只用「感觉不抖」。</p>',7)),(e(),s(p,null,{default:i(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20GND%5B%22%E5%9C%B0%E8%84%89%E5%8A%A8%22%5D%20--%3E%20ISO%5B%22%E9%9A%94%E6%8C%AF%22%5D%0A%20%20PUMP%5B%22%E6%B3%B5%20%2F%20%E7%A9%BA%E8%B0%83%22%5D%20--%3E%20ISO%0A%20%20ISO%20--%3E%20STAGE%5B%22%E5%B7%A5%E4%BB%B6%E5%8F%B0%E4%BC%BA%E6%9C%8D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">浸没头流体力是机内扰动，隔振挡不住，要靠台伺服与流体设计。分内外源。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>隔振传递函数在低频硬、高频软；主动环补中间带。过隔振会让台「飘」，与对准捕捉冲突，要折中。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课台自己加速扫描时的反作用，是隔振之后仍要管的力。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>减振把厂频谱从套刻预算里抠掉一块。</li><li>验收看传递函数，不只看静标。</li><li>出处：扫描机 isolation 通识；套刻课。</li></ul>',7))])}const T=r(_,[["render",c]]);export{b as __pageData,T as default};
